{
  "contract": "BadBunnyNFTS",
  "closure": {
    "site_function": "teamPayout",
    "site_call": ".transfer",
    "functions": [
      "<fallback>",
      "claimMintRewards",
      "mint",
      "teamPayout"
    ],
    "justification": "Includes all functions that can be called during the risky site, including the function itself and any external functions that can modify the exposed storage."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "claimMintRewards",
      "mint"
    ],
    "nesting_bound": {
      "teamPayout": 1
    }
  },
  "phases": {
    "function": "teamPayout",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_transfer"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_transfer",
      "to_marker": "after_transfer"
    },
    "post": {
      "name": "post",
      "from_marker": "after_transfer",
      "to_marker": "end"
    },
    "linearization_point": "after_transfer"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of assets in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_balanceDistributor <= _ethBal + inFlight",
    "stable_formula": "_balanceDistributor <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "_balanceDistributor <= _ethBal",
    "rule": "The exposure invariant ensures that the target property holds even with in-flight changes during the callback window."
  }
}
